/* WHAT'S IN THIS FILE (studio/web/brand-drawing.js)
   THE FARM'S BRAND (Laynie, Oct 29: "i also want to add our logo as a brand for our livestock, with studio support").
   window.FarmBrand, for the studio (to place it: the Brand panel) and the Companion (to draw it on everybody, with the
   messes: extension/src/messes.js). The art is the B&B logo cut from reference/image reference/logo.jpg by its ink
   (shared/brand/brand-mark.png, brand-full.png): MARK the big BB with the paw-print cowbell, FULL the whole logo.
   FarmBrand.paint(g, mask, brand, ox, oy, over) puts it on canvas g, kept to the skin in mask (or null).
   A brand: { art: "mark"|"full", place, size (px tall), angle, dx, dy, look: "seared"|"healed"|"ink", flip }
*/
(() => {
const BRAND_ART = {
  mark: { src: "data:image/png;base64,", w: 205, h: 220 },
  full: { src: "data:image/png;base64,", w: 299, h: 360 },
};


// where it can go, on the game's 500-wide body (y counted from the top of the body, not the canvas): [x, y, angle]
const BRAND_PLACES = {
  hipL: { label: "Left hip", at: [192, 528, -12] },      hipR: { label: "Right hip", at: [308, 528, 12] },
  thighL: { label: "Left thigh", at: [212, 640, -4] },   thighR: { label: "Right thigh", at: [288, 640, 4] },
  mons: { label: "Low on the belly", at: [250, 515, 0] }, tummy: { label: "Tummy", at: [250, 455, 0] },
  chestL: { label: "Left breast, up top", at: [205, 288, -6] }, chestR: { label: "Right breast, up top", at: [295, 288, 6] },
  shoulderL: { label: "Left shoulder", at: [170, 262, -18] }, shoulderR: { label: "Right shoulder", at: [330, 262, 18] },
};
const BRAND_LOOKS = { seared: "Fresh and seared", healed: "Healed, pale and raised", ink: "Inked black" };
const BRAND_DEFAULT = { art: "mark", place: "hipR", size: 46, angle: 0, dx: 0, dy: 0, look: "seared", flip: false };

function cleanBrand(b) {
  if (!b || typeof b !== "object") return null;
  const n = (v, lo, hi, d) => (Number.isFinite(+v) ? Math.max(lo, Math.min(hi, +v)) : d);
  return {
    art: b.art === "full" ? "full" : "mark", place: BRAND_PLACES[b.place] ? b.place : BRAND_DEFAULT.place,
    size: n(b.size, 16, 200, BRAND_DEFAULT.size), angle: n(b.angle, -180, 180, 0), dx: n(b.dx, -80, 80, 0), dy: n(b.dy, -80, 80, 0),
    look: BRAND_LOOKS[b.look] ? b.look : "seared", flip: !!b.flip,
  };
}

const imgs = {};
function art(which) {
  const A = BRAND_ART[which] || BRAND_ART.mark;
  let i = imgs[which];
  if (!i) { i = imgs[which] = new Image(); i.src = A.src; }
  return i.complete && i.naturalWidth ? i : null;
}
const brandReady = (b) => !!art((b && b.art) || "mark");

// the brand's own picture, coloured for its look (made once per art, look and size)
const made = new Map();
function stamp(b) {
  const key = b.art + "|" + b.look + "|" + Math.round(b.size), was = made.get(key); if (was) return was;
  const i = art(b.art); if (!i) return null;
  const h = Math.round(b.size), w = Math.round(i.naturalWidth * h / i.naturalHeight), pad = 6;
  const c = document.createElement("canvas"); c.width = w + pad * 2; c.height = h + pad * 2; const g = c.getContext("2d");
  const tint = (color, alpha, blur, grow) => {
    const t = document.createElement("canvas"); t.width = c.width; t.height = c.height; const tg = t.getContext("2d");
    if (blur) tg.filter = "blur(" + blur + "px)";
    const gw = w * (grow || 1), gh = h * (grow || 1);
    tg.drawImage(i, pad + (w - gw) / 2, pad + (h - gh) / 2, gw, gh); tg.filter = "none";
    tg.globalCompositeOperation = "source-in"; tg.fillStyle = color; tg.fillRect(0, 0, t.width, t.height);
    g.globalAlpha = alpha; g.drawImage(t, 0, 0); g.globalAlpha = 1;
  };
  if (b.look === "ink") tint("#16120f", 0.85, 0.4);
  else if (b.look === "healed") { tint("#e7b6a6", 0.55, 2.2, 1.04); tint("#f3d2c4", 0.75, 0.6); tint("#ffffff", 0.18, 0); }
  else { tint("#c8574a", 0.5, 3, 1.06); tint("#7a2418", 0.85, 0.8); tint("#3a120c", 0.55, 0.3); }   // seared: an angry red halo, a dark burnt core
  made.set(key, c); if (made.size > 24) made.delete(made.keys().next().value);
  return c;
}

// paint it: g the canvas, mask the skin (or null), ox/oy where the body sits, over the canvas' top overflow
function paintBrand(g, mask, brand, ox, oy, over) {
  const b = cleanBrand(brand); if (!b) return false;
  const s = stamp(b); if (!s) return false;
  const P = BRAND_PLACES[b.place].at, x = P[0] + b.dx + (ox || 0), y = P[1] + b.dy + (over || 0) + (oy || 0);
  const W0 = g.canvas.width, H0 = g.canvas.height;
  const t = document.createElement("canvas"); t.width = W0; t.height = H0; const tg = t.getContext("2d");
  tg.translate(x, y); tg.rotate(((P[2] + b.angle) * Math.PI) / 180); if (b.flip) tg.scale(-1, 1);
  tg.drawImage(s, -s.width / 2, -s.height / 2);
  tg.setTransform(1, 0, 0, 1, 0, 0);
  if (mask) { tg.globalCompositeOperation = "destination-in"; tg.drawImage(mask, 0, 0); tg.globalCompositeOperation = "source-over"; }   // only on skin
  g.drawImage(t, 0, 0);
  return true;
}

window.FarmBrand = { ART: BRAND_ART, PLACES: BRAND_PLACES, LOOKS: BRAND_LOOKS, DEFAULT: BRAND_DEFAULT, clean: cleanBrand, paint: paintBrand, ready: brandReady };
})();
